def transform(grid):
    from collections import Counter

    # Count frequencies to find background color
    counts = Counter()
    for row in grid:
        for cell in row:
            counts[cell] += 1
    bg_color = counts.most_common(1)[0][0]

    h = len(grid)
    w = len(grid[0])

    # Find the Key Column (column with most unique values)
    key_col_idx = -1
    max_unique = -1

    for c in range(w):
        vals = set()
        for r in range(h):
            vals.add(grid[r][c])
        if len(vals) > max_unique:
            max_unique = len(vals)
            key_col_idx = c

    # Generate pattern (reversed key column values)
    pattern = []
    if key_col_idx != -1:
        col_vals = [grid[r][key_col_idx] for r in range(h)]
        pattern = col_vals[::-1]
    else:
        pattern = [0]

    # Find first column that is entirely background color
    start_col = 0
    for c in range(w):
        all_bg = True
        for r in range(h):
            if grid[r][c] != bg_color:
                all_bg = False
                break
        if all_bg:
            start_col = c
            break

    # Construct output grid
    result = [row[:] for row in grid]
    len_p = len(pattern)

    if start_col < w:
        for r in range(h):
            for c in range(w):
                if result[r][c] == bg_color:
                    result[r][c] = pattern[(c - start_col) % len_p]

    return result
